INSERT INTO wines (id, name, producer, type, grape, origin, price, price_old, img, badge, featured, date, description, alcohol, acidity, volume, serving_temp, traits, pairings) VALUES
  (1, 'Primitivo di Manduria', 'Brisa Vinícola', 'Tinto', 'Syrah', '🇮🇹 Itália', 119.9, 149.9, 'garrafa.png', '20% OFF', 0, 5, 'Um vinho de corpo pleno e personalidade marcante, com notas de ameixa madura, chocolate amargo e especiarias finas. Cor rubi profunda, límpido e brilhante. Em boca apresenta taninos maduros, acidez equilibrada e retrogosto longo e persistente.', '14%', '5,8 g/L', '750ml', '16°C a 18°C', '["Encorpado", "Frutado intenso", "Taninos firmes", "Longa persistência"]', '["Carnes grelhadas", "Massas robustas", "Queijos curados"]'),
  (2, 'Chardonnay Reserva', 'Brisa Vinícola', 'Branco', 'Sauvignon Blanc', '🇫🇷 França', 94.9, NULL, 'garrafa.png', NULL, 0, 4, 'Branco elegante e fresco, com aromas cítricos e florais que se equilibram com notas minerais. Passagem suave em boca, acidez vibrante e final limpo — ideal para quem aprecia vinhos leves e aromáticos.', '12,5%', '6,1 g/L', '750ml', '8°C a 10°C', '["Leve", "Fresco", "Aromático", "Final limpo"]', '["Frutos do mar", "Saladas", "Queijos frescos"]'),
  (3, 'Brut Rosé Grand Cru', 'Brisa Vinícola', 'Espumante', 'Blend', '🇧🇷 Brasil', 87.9, 109.9, 'garrafa.png', '20% OFF', 0, 6, 'Espumante rosé de borbulhas finas e persistentes, com aromas de frutas vermelhas e um toque floral delicado. Perfeito para celebrações e momentos especiais, com acidez equilibrada e final refrescante.', '12%', '6,8 g/L', '750ml', '6°C a 8°C', '["Borbulhas finas", "Frutado", "Elegante", "Refrescante"]', '["Aperitivos", "Sobremesas leves", "Frutos do mar"]'),
  (4, 'Marselan Reserva', 'Brisa Vinícola', 'Tinto', 'Marselan', '🇧🇷 Brasil', 79.9, NULL, 'garrafa.png', NULL, 0, 3, 'Tinto brasileiro de caráter frutado e taninos macios, com notas de amora e especiarias suaves. Um vinho versátil, agradável tanto para o dia a dia quanto para ocasiões especiais.', '13%', '5,5 g/L', '750ml', '16°C a 18°C', '["Frutado", "Taninos macios", "Versátil"]', '["Carnes vermelhas", "Massas com molho de tomate", "Queijos amarelos"]'),
  (5, 'Moscato Bianco', 'Brisa Vinícola', 'Branco', 'Moscato', '🇮🇹 Itália', 67.9, NULL, 'garrafa.png', NULL, 0, 2, 'Branco doce e aromático, com notas de flor de laranjeira, pêssego e mel. Leve e com baixo teor alcoólico, é a escolha perfeita para quem busca um vinho descontraído e perfumado.', '7,5%', '5,0 g/L', '750ml', '6°C a 8°C', '["Doce", "Aromático", "Leve"]', '["Sobremesas", "Frutas", "Queijos suaves"]'),
  (6, 'Bordô Clássico', 'Brisa Vinícola', 'Tinto', 'Bordô', '🇧🇷 Brasil', 54.9, 74.9, 'garrafa.png', '27% OFF', 0, 1, 'A uva mais tradicional do Brasil em um vinho simples e saboroso, com notas de frutas vermelhas maduras e final levemente adocicado. Um clássico acessível para o dia a dia.', '11,5%', '5,2 g/L', '750ml', '14°C a 16°C', '["Frutado", "Acessível", "Tradicional"]', '["Petiscos", "Pizza", "Queijos frescos"]'),
  (7, 'Espumante Moscatel', 'Brisa Vinícola', 'Espumante', 'Moscato', '🇧🇷 Brasil', 59.9, NULL, 'garrafa.png', NULL, 0, 7, 'Espumante doce e aromático, com borbulhas suaves e notas de uva fresca e flores brancas. Um favorito nacional para celebrar momentos simples e especiais.', '7%', '5,8 g/L', '750ml', '6°C a 8°C', '["Doce", "Aromático", "Festivo"]', '["Sobremesas", "Frutas", "Brindes"]'),
  (8, 'Syrah Reserva Especial', 'Brisa Vinícola', 'Tinto', 'Syrah', '🇦🇷 Argentina', 139.9, 179.9, 'garrafa.png', '22% OFF', 0, 8, 'Tinto argentino encorpado e intenso, com notas de frutas negras, pimenta preta e um toque de carvalho. Taninos estruturados e final longo, para apreciadores de vinhos robustos.', '14,5%', '6,0 g/L', '750ml', '16°C a 18°C', '["Encorpado", "Especiado", "Estruturado", "Final longo"]', '["Carnes grelhadas", "Churrasco", "Queijos curados"]'),
  (9, 'Rosé de Provence', 'Brisa Vinícola', 'Rosé', 'Blend', '🇫🇷 França', 99.9, NULL, 'garrafa.png', NULL, 0, 9, 'Rosé francês clássico, seco e delicado, com notas de morango silvestre e pétalas de rosa. Cor salmão suave e acidez equilibrada — elegância em cada taça.', '12,5%', '5,6 g/L', '750ml', '8°C a 10°C', '["Seco", "Delicado", "Elegante"]', '["Saladas", "Frutos do mar", "Culinária mediterrânea"]'),
  (10, 'Sauvignon Blanc Clássico', 'Brisa Vinícola', 'Branco', 'Sauvignon Blanc', '🇳🇿 Nova Zelândia', 84.9, NULL, 'garrafa.png', NULL, 0, 10, 'Branco vibrante com os clássicos aromas cítricos e herbáceos da Nova Zelândia — maracujá, lima e capim-limão. Acidez marcante e corpo leve, ótimo para o calor.', '13%', '6,5 g/L', '750ml', '8°C a 10°C', '["Cítrico", "Herbáceo", "Vibrante"]', '["Frutos do mar", "Ceviche", "Queijos de cabra"]'),
  (11, 'Blend Premium', 'Brisa Vinícola', 'Tinto', 'Blend', '🇧🇷 Brasil', 159.9, NULL, 'garrafa.png', NULL, 1, 11, 'Nosso corte premium, combinando uvas selecionadas para um vinho complexo e equilibrado — notas de frutas negras, especiarias e um sutil toque de baunilha do carvalho. Taninos sedosos e final persistente.', '14%', '5,7 g/L', '750ml', '16°C a 18°C', '["Complexo", "Sedoso", "Premium", "Final persistente"]', '["Carnes nobres", "Risotos", "Queijos maturados"]'),
  (12, 'Rosé Brut Extra', 'Brisa Vinícola', 'Rosé', 'Marselan', '🇧🇷 Brasil', 72.9, 89.9, 'garrafa.png', '19% OFF', 0, 12, 'Espumante rosé brasileiro, seco e refrescante, com notas de framboesa e um toque mineral. Borbulhas constantes e acidez bem marcada tornam esse vinho perfeito para brindar.', '12%', '6,3 g/L', '750ml', '6°C a 8°C', '["Seco", "Refrescante", "Mineral"]', '["Aperitivos", "Sushi", "Petiscos salgados"]');